Hmm, cleaner: manage as turns:

```c
typedef struct { char user[HIST_TEXT_MAX]; char bot[HIST_TEXT_MAX]; } hist_turn_t;
static hist_turn_t s_hist[HIST_TURN_MAX];
static int s_hist_n;

void dm_chat_hist_push(const char *user, const char *assistant)
{
  if (!user || !user[0]) return;
  if (s_hist_n == HIST_TURN_MAX)
    {
      memmove(&s_hist[0], &s_hist[1], sizeof(hist_turn_t) * (HIST_TURN_MAX - 1));
      s_hist_n = HIST_TURN_MAX - 1;
    }
  strncpy(s_hist[s_hist_n].user, user, HIST_TEXT_MAX - 1);
  s_hist[s_hist_n].user[HIST_TEXT_MAX-1] = 0;
  s_hist[s_hist_n].bot[0] = 0;
  if (assistant && assistant[0])
    {
      strncpy(s_hist[s_hist_n].bot, assistant, HIST_TEXT_MAX - 1);
      s_hist[s_hist_n].bot[HIST_TEXT_MAX-1] = 0;
    }
  s_hist_n++;
}

int dm_chat_hist_json(char *out, int cap)
{
  /* each entry emitted as ,{"role":"user","content":".."},{"role":"assistant","content":".."} */
  size_t o = 0;
  int i;
  out[0] = 0;
  for (i = 0; i < s_hist_n; i++)
    {
      char eu[HIST_TEXT_MAX * 2];
      char ea[HIST_TEXT_MAX * 2];
      int n;
      json_escape(s_hist[i].user, eu, sizeof(eu));
      n = snprintf(out + o, cap - o, ",{\"role\":\"user\",\"content\":\"%s\"}", eu);
      if (n <= 0 || (size_t)n >= cap - o) { out[o] = 0; return -1; }
      o += n;
      if (s_hist[i].bot[0])
        {
          json_escape(s_hist[i].bot, ea, sizeof(ea));
          n = snprintf(out + o, cap - o, ",{\"role\":\"assistant\",\"content\":\"%s\"}", ea);
          if (n <= 0 || (size_t)n >= cap - o) { out[o] = 0; return -1; }
          o += n;
        }
    }
  return (int)o;
}
```

