/* raw PCM record to WAV — reliable on this board (pcm0c works) */
static void wav_hdr(FILE *f, uint32_t data_bytes)
{
  uint32_t byte_rate = REC_RATE * REC_CH * (REC_BITS / 8);
  uint16_t block_align = REC_CH * (REC_BITS / 8);
  uint8_t hdr[44];
  uint32_t riff = 36 + data_bytes;
  uint32_t fmt_sz = 16;
  uint16_t fmt = 1, ch = REC_CH, bits = REC_BITS;
  uint32_t rate = REC_RATE;

  memset(hdr, 0, sizeof(hdr));
  memcpy(hdr, "RIFF", 4);
  memcpy(hdr + 4, &riff, 4);
  memcpy(hdr + 8, "WAVEfmt ", 8);
  memcpy(hdr + 16, &fmt_sz, 4);
  memcpy(hdr + 20, &fmt, 2);
  memcpy(hdr + 22, &ch, 2);
  memcpy(hdr + 24, &rate, 4);
  memcpy(hdr + 28, &byte_rate, 4);
  memcpy(hdr + 32, &block_align, 2);
  memcpy(hdr + 34, &bits, 2);
  memcpy(hdr + 36, "data", 4);
  memcpy(hdr + 40, &data_bytes, 4);
  fwrite(hdr, 1, 44, f);
}

static void *rec_thread(void *arg)
{
  int max_sec = (int)(intptr_t)arg;
  char buf[1024];
  size_t got = 0;
  size_t want;
  FILE *out;
  int fd;

  if (max_sec <= 0)
    {
      max_sec = REC_MAX_SEC;
    }
  want = (size_t)max_sec * REC_RATE * (REC_BITS / 8);

  s_st = DM_VOICE_REC;
  fd = open("/dev/audio/pcm0c", O_RDONLY);
  if (fd < 0)
    {
      s_rec_active = 0;
      s_st = DM_VOICE_ERR;
      return NULL;
    }
#ifdef AUDIOIOC_RESERVE
  (void)ioctl(fd, AUDIOIOC_RESERVE, 0);
#endif
#ifdef AUDIOIOC_CONFIGURE
  {
    struct audio_caps_desc_s cap;
    memset(&cap, 0, sizeof(cap));
    cap.caps.ac_len = sizeof(struct audio_caps_s);
    cap.caps.ac_type = AUDIO_TYPE_INPUT;
    cap.caps.ac_channels = REC_CH;
    cap.caps.ac_controls.hw[0] = (uint16_t)REC_RATE;
    cap.caps.ac_controls.b[2] = (uint8_t)REC_BITS;
    (void)ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&cap);
  }
#endif

  out = fopen(WAV_REC, "wb");
  if (!out)
    {
      close(fd);
      s_rec_active = 0;
      s_st = DM_VOICE_ERR;
      return NULL;
    }
  wav_hdr(out, 0);
  s_rec_fd = fd;

  while (!s_rec_stop && got < want)
    {
      ssize_t n = read(fd, buf, sizeof(buf));
      if (n <= 0)
        {
          break;
        }
      fwrite(buf, 1, (size_t)n, out);
      got += (size_t)n;
    }

  {
    uint32_t data_bytes = (uint32_t)got;
    fseek(out, 4, SEEK_SET);
    {
      uint32_t riff = 36 + data_bytes;
      fwrite(&riff, 4, 1, out);
    }
    fseek(out, 40, SEEK_SET);
    fwrite(&data_bytes, 4, 1, out);
    fclose(out);
  }
  if (s_rec_fd >= 0)
    {
      close(s_rec_fd);
      s_rec_fd = -1;
    }
  else
    {
      close(fd);
    }
  s_rec_active = 0;
  s_st = DM_VOICE_IDLE;
  return NULL;
}

int dm_voice_rec_start(int max_seconds)
{
  if (s_rec_active)
    {
      return 0;
    }
  s_rec_stop = 0;
  s_rec_active = 1;
  s_st = DM_VOICE_REC;
  if (pthread_create(&s_rec_th, NULL, rec_thread,
                     (void *)(intptr_t)max_seconds) != 0)
    {
      s_rec_active = 0;
      s_st = DM_VOICE_ERR;
      return -1;
    }
  pthread_detach(s_rec_th);
  return 0;
}

int dm_voice_rec_stop(void)
{
  int i;

  if (!s_rec_active)
    {
      FILE *f = fopen(WAV_REC, "rb");
      if (f)
        {
          fclose(f);
          return 0;
        }
      return -1;
    }

  s_rec_stop = 1;
  if (s_rec_fd >= 0)
    {
      int fd = s_rec_fd;
      s_rec_fd = -1;
      close(fd); /* unblock read() */
    }
  for (i = 0; i < 50 && s_rec_active; i++)
    {
      usleep(10 * 1000);
    }

  {
    FILE *f = fopen(WAV_REC, "rb");
    if (!f)
      {
        return -1;
      }
    fclose(f);
    return 0;
  }
}
