static int play_wav_raw(const char *path)
{
  FILE *f = fopen(path, "rb");
  int fd;
  char buf[1024];
  size_t n;
  uint8_t hdr[44];
  uint32_t rate = REC_RATE;
  uint16_t ch = REC_CH;
  uint16_t bits = REC_BITS;

  if (!f)
    {
      return -1;
    }
  if (fread(hdr, 1, 44, f) != 44 || memcmp(hdr, "RIFF", 4) != 0)
    {
      fclose(f);
      return -1;
    }

  /* read fmt fields from the canonical 44-byte WAV header */
  ch = (uint16_t)(hdr[22] | (hdr[23] << 8));
  rate = (uint32_t)(hdr[24] | (hdr[25] << 8) | (hdr[26] << 16) |
                    ((uint32_t)hdr[27] << 24));
  bits = (uint16_t)(hdr[34] | (hdr[35] << 8));
  if (rate < 8000 || rate > 48000)
    {
      rate = REC_RATE;
    }
  if (ch < 1 || ch > 2)
    {
      ch = 1;
    }
  if (bits != 8 && bits != 16)
    {
      bits = 16;
    }

  fd = open("/dev/audio/pcm0p", O_WRONLY);
  if (fd < 0)
    {
      fclose(f);
      return -1;
    }
#ifdef AUDIOIOC_RESERVE
  (void)ioctl(fd, AUDIOIOC_RESERVE, 0);
#endif
#ifdef AUDIOIOC_CONFIGURE
  {
    struct audio_caps_desc_s cap;
    memset(&cap, 0, sizeof(cap));
    cap.caps.ac_len = sizeof(struct audio_caps_s);
    cap.caps.ac_type = AUDIO_TYPE_OUTPUT;
    cap.caps.ac_channels = (uint8_t)ch;
    cap.caps.ac_controls.hw[0] = (uint16_t)rate;
    cap.caps.ac_controls.b[2] = (uint8_t)bits;
    (void)ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&cap);
  }
#endif
  while ((n = fread(buf, 1, sizeof(buf), f)) > 0)
    {
      if (write(fd, buf, n) < 0)
        {
          break;
        }
    }
#ifdef AUDIOIOC_RELEASE
  (void)ioctl(fd, AUDIOIOC_RELEASE, 0);
#endif
  close(fd);
  fclose(f);
  return 0;
}

static int play_wav(const char *path)
{
  int i;

  /* always target pcm0p: even with "headset" output selected and no
     headset present, the reply must still reach the speaker */

  if (path && strcmp(path, WAV_TTS) != 0)
    {
      char cmd[96];
      snprintf(cmd, sizeof(cmd), "cp %s %s 2>/dev/null", path, WAV_TTS);
      (void)system(cmd);
      path = WAV_TTS;
    }

  uv_ensure();
  s_play_done = 0;
  s_play_started = 0;
