```c
static int wav_strip_header(const char *path, uint32_t *rate, uint16_t *ch,
                            uint16_t *bits)
{
  FILE *f = fopen(path, "rb");
  FILE *o;
  uint8_t hdr[44];
  char buf[1024];
  size_t n;

  *rate = 0; *ch = 0; *bits = 0;
  if (!f) return -1;
  if (fread(hdr, 1, 44, f) != 44 || memcmp(hdr, "RIFF", 4) != 0)
    { fclose(f); return -1; }
  *ch = hdr[22] | (hdr[23] << 8);
  *rate = hdr[24] | (hdr[25] << 8) | (hdr[26] << 16) | ((uint32_t)hdr[27] << 24);
  *bits = hdr[34] | (hdr[35] << 8);
  o = fopen(PCM_RAW, "wb");
  if (!o) { fclose(f); return -1; }
  while ((n = fread(buf, 1, sizeof(buf), f)) > 0)
    fwrite(buf, 1, n, o);
  fclose(o);
  fclose(f);
  return 0;
}

static int play_wav(const char *path)
{
  uint32_t rate;
  uint16_t ch, bits;
  const char *src = (path && path[0]) ? path : WAV_TTS;

  if (!s_play)
    {
      s_play = nxplayer_create();
      if (!s_play) return -1;
      (void)nxplayer_setdevice(s_play, "/dev/audio/pcm0p");
    }

  if (wav_strip_header(src, &rate, &ch, &bits) != 0)
    return -1;
  if (rate < 8000 || rate > 48000) rate = 24000;
  if (ch < 1 || ch > 2) ch = 1;
  if (bits != 8 && bits != 16) bits = 16;

  (void)nxplayer_stop(s_play);
  return (nxplayer_playraw(s_play, PCM_RAW, AUDIO_FMT_PCM, 0,
                           (uint8_t)ch, (uint8_t)bits, rate, 1) == OK) ? 0 : -1;
}
